import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"ReserveLocalMemory","description":"","frontmatter":{},"headers":[{"level":1,"title":"ReserveLocalMemory","slug":"reservelocalmemory"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/平台信息获取/PlatformAscendC/ReserveLocalMemory.md","filePath":"api/Utils-API/平台信息获取/PlatformAscendC/ReserveLocalMemory.md"}'),l={name:"api/Utils-API/平台信息获取/PlatformAscendC/ReserveLocalMemory.md"};function r(o,e,i,p,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="reservelocalmemory" tabindex="-1">ReserveLocalMemory <a class="header-anchor" href="#reservelocalmemory" aria-label="Permalink to &quot;ReserveLocalMemory&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>该函数用于在Unified Buffer中预留指定大小的内存空间。调用该接口后，使用<a href="./GetCoreMemSize.html">GetCoreMemSize</a>可以获取实际可用的剩余Unified Buffer空间大小。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void ReserveLocalMemory(ReservedSize size)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>ReservedSize</td><td>输入</td><td>需要预留的空间大小。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;zh-cn_topic_0000001597681768_zh-cn_topic_0000001442486577_screen12645740154518&quot;&gt;enum class ReservedSize { RESERVED_SIZE_8K, // 预留8 * 1024B空间 RESERVED_SIZE_16K, // 预留16 * 1024B空间 RESERVED_SIZE_32K, // 预留32 * 1024B空间 };&lt;/pre&gt;</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>多次调用该函数时，仅保留最后一次调用的结果。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ge::graphStatus TilingXXX(gert::TilingContext* context) {</span></span>
<span class="line"><span>    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>    uint64_t ub_size, l1_size;</span></span>
<span class="line"><span>    // 预留8KB的Unified Buffer内存空间</span></span>
<span class="line"><span>    ascendcPlatform.ReserveLocalMemory(platform_ascendc::ReservedSize::RESERVED_SIZE_8K);</span></span>
<span class="line"><span>    // 获取Unified Buffer和L1的实际可用内存大小</span></span>
<span class="line"><span>    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub_size);</span></span>
<span class="line"><span>    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, l1_size);</span></span>
<span class="line"><span>    // ...</span></span>
<span class="line"><span>    return ret;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>完整样例可参考<a href="./../../../SIMD-API/高阶API/数学计算/更多样例-83.html#section577043422516">与数学库高阶API配合使用的样例</a>。</p>`,14)])])}const u=a(l,[["render",r]]);export{m as __pageData,u as default};
